import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Definições","description":"","frontmatter":{},"headers":[],"relativePath":"pt/repair-station-business/settings.md","filePath":"pt/repair-station-business/settings.md"}'),r={name:"pt/repair-station-business/settings.md"};function s(i,t,c,n,p,h){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="definicoes" tabindex="-1">Definições <a class="header-anchor" href="#definicoes" aria-label="Permalink to &quot;Definições&quot;">​</a></h1><p>Cada definição da Repair Station Business edita-se no <code>/nay</code>, na página <strong>Repair Station Business</strong> (scope <code>nay_repair_business.config</code>). As alterações são guardadas na base de dados e aplicadas a todos os jogadores de uma vez. O <code>config.lua</code> contém valores iniciais opcionais: aplicam-se até uma definição ser alterada no <code>/nay</code>, e <strong>Repor</strong> volta a eles.</p><p>A coluna <strong>No /nay</strong> mostra o nome apresentado no painel. A chave é o nome usado pelo <code>config.lua</code> e pela <a href="/pt/nay-lib/api">API HTTP</a>.</p><h2 id="geral" tabindex="-1">Geral <a class="header-anchor" href="#geral" aria-label="Permalink to &quot;Geral&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Ativado</td><td><code>Enabled</code></td><td>ligado / desligado</td><td>ligado</td><td>Ativa ou desativa as funções de propriedade. Desativadas, as estações comportam-se como simples Repair Stations.</td></tr><tr><td>Estações à venda sem proprietário</td><td><code>UnownedMode</code></td><td><code>open</code> ou <code>closed</code></td><td><code>open</code></td><td>Aberta: os jogadores ainda podem reparar lá. Fechada: a estação recusa reparações até alguém a comprar.</td></tr></tbody></table><h2 id="propriedade" tabindex="-1">Propriedade <a class="header-anchor" href="#propriedade" aria-label="Permalink to &quot;Propriedade&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Estações à venda</td><td><code>Purchasable</code></td><td>lista, até 64</td><td>nenhuma</td><td>Estações que os jogadores podem comprar. Use o painel de administração para as gerir no jogo.</td></tr><tr><td>Estações por jogador</td><td><code>MaxStationsPerPlayer</code></td><td>número, 1 a 16</td><td>1</td><td>Quantas estações um jogador pode possuir.</td></tr><tr><td>Conta de compra</td><td><code>BuyAccount</code></td><td><code>cash</code> ou <code>bank</code></td><td><code>bank</code></td><td>Conta de onde o preço de compra é cobrado.</td></tr><tr><td>Recompra (%)</td><td><code>SellBackPercent</code></td><td>número, 0 a 100</td><td>50</td><td>Parte do preço de compra devolvida quando o proprietário vende ou perde a estação.</td></tr><tr><td>Limite de inatividade (dias)</td><td><code>InactivityDays</code></td><td>número, 0 a 90</td><td>14</td><td>Um proprietário que não abre o tablet durante este tempo perde a estação e é reembolsado. 0 desativa.</td></tr></tbody></table><h2 id="stock" tabindex="-1">Stock <a class="header-anchor" href="#stock" aria-label="Permalink to &quot;Stock&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Capacidade do stock</td><td><code>Capacity</code></td><td>número, 10 a 10000</td><td>100</td><td>Número máximo de peças que uma estação pode conter.</td></tr><tr><td>Peças para o motor</td><td><code>PartsEngine</code></td><td>número, 0 a 100</td><td>2</td><td>Peças usadas por um serviço que repara o motor.</td></tr><tr><td>Peças para a carroçaria</td><td><code>PartsBody</code></td><td>número, 0 a 100</td><td>3</td><td>Peças usadas por um serviço que repara a carroçaria.</td></tr><tr><td>Peças para os pneus</td><td><code>PartsTyres</code></td><td>número, 0 a 100</td><td>1</td><td>Peças usadas por um serviço que repara os pneus.</td></tr><tr><td>Modo de reposição</td><td><code>RestockMode</code></td><td><code>purchase</code>, <code>items</code> ou <code>both</code></td><td><code>both</code></td><td>Como os proprietários enchem o stock.</td></tr><tr><td>Preço por peça</td><td><code>PartPrice</code></td><td>número, 0 a 100000</td><td>40</td><td>Pago a partir do banco do proprietário ao comprar peças.</td></tr><tr><td>Objeto de peças</td><td><code>PartItem</code></td><td>texto, 1 a 64 caracteres</td><td><code>repair_parts</code></td><td>Objeto do inventário entregue para repor o stock.</td></tr><tr><td>Peças por objeto</td><td><code>PartsPerItem</code></td><td>número, 1 a 100</td><td>5</td><td>Peças que um objeto adiciona ao stock.</td></tr><tr><td>Alerta de stock baixo</td><td><code>LowStockThreshold</code></td><td>número, 0 a 10000</td><td>10</td><td>O proprietário é avisado quando o stock desce abaixo deste número. 0 desativa.</td></tr></tbody></table><h2 id="precos" tabindex="-1">Preços <a class="header-anchor" href="#precos" aria-label="Permalink to &quot;Preços&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Preço mais baixo (%)</td><td><code>MinPricePercent</code></td><td>número, 10 a 100</td><td>50</td><td>Parte mais baixa do preço do serviço que um proprietário pode definir.</td></tr><tr><td>Preço mais alto (%)</td><td><code>MaxPricePercent</code></td><td>número, 100 a 500</td><td>200</td><td>Parte mais alta do preço do serviço que um proprietário pode definir.</td></tr><tr><td>Imposto (%)</td><td><code>TaxPercent</code></td><td>número, 0 a 90</td><td>10</td><td>Parte de cada pagamento de reparação que não chega à caixa.</td></tr></tbody></table><h2 id="mapa" tabindex="-1">Mapa <a class="header-anchor" href="#mapa" aria-label="Permalink to &quot;Mapa&quot;">​</a></h2><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th><th>Predefinição</th><th>Descrição</th></tr></thead><tbody><tr><td>Cor do blip de uma estação própria</td><td><code>OwnedBlipColor</code></td><td>número, 0 a 85</td><td>2</td><td>Cor do blip das estações que possui, no seu mapa.</td></tr><tr><td>Cor do blip de uma estação à venda</td><td><code>ForSaleBlipColor</code></td><td>número, 0 a 85</td><td>5</td><td>Cor do blip das estações à venda.</td></tr></tbody></table><p>Entradas de <strong>Estações à venda</strong>:</p><table tabindex="0"><thead><tr><th>No /nay</th><th>Chave</th><th>Tipo</th></tr></thead><tbody><tr><td>Identificador da estação</td><td><code>StationId</code></td><td>8 caracteres (0 a 9, a a f), como no editor da Repair Station.</td></tr><tr><td>Preço</td><td><code>Price</code></td><td>número, 0 a 100000000</td></tr></tbody></table><p>As percentagens do proprietário (<code>MinPricePercent</code>, <code>MaxPricePercent</code>) aplicam-se ao preço de cada serviço, antes dos descontos de emprego. O imposto (<code>TaxPercent</code>) é retirado de cada pagamento de reparação antes de chegar à caixa.</p>',16)])])}const u=e(r,[["render",s]]);export{m as __pageData,u as default};
